programa
{
    funcao inicio()
    {
        inteiro opcao
        escreva("1 - Inscrição\n2 - Calendário\n")
        leia(opcao)
        escolha (opcao)
        {
            caso 1:
                escreva("Inscrição")
                pare
            caso 2:
                escreva("Calendário")
                pare
            caso contrario:
                escreva("Inválida")
        }
    }
}
